action.command:
cat > /tmp/verify/validate_search.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push('pageerror: ' + e.message));
    page.on('requestfailed', r => errors.push('reqfail: ' + r.url()));
    const out = {};
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(4000);
    await page.selectOption('#chooseIndex', { label: 'spotify_tracks' });
    await page.waitForTimeout(5000);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('#dataExplorerDataFields', { label: 'artists.name.keyword' });
    await page.waitForTimeout(3000);
    // open output collapsible and pick barChart
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(1000);
    const outSel = await page.$eval('.chartTypeChooser', el => el.options.length).catch(e => 'ERR');
    out.outputOptions = outSel;
    await page.selectOption('.chartTypeChooser', { label: 'barChart' });
    await page.waitForTimeout(1000);
    await page.click('#getResults');
    await page.waitForTimeout(10000);
    out.svgCount = await page.locator('#graphicsWrapper svg').count();
    out.svgRectCount = await page.locator('#graphicsWrapper svg rect').count();
    out.tableRows = await page.locator('#graphicsWrapper table tr').count().catch(()=>0);
    out.feedback = (await page.$eval('#feedbackText', el => el.textContent.trim()).catch(() => '')) || '(empty)';
    await page.screenshot({ path: '/tmp/verify/final_search_chart.png', fullPage: true });
    out.errors = errors;
    console.log('SEARCH_RESULTS:' + JSON.stringify(out, null, 2));
    await browser.close();
})().catch(e => { console.error('SEARCH_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node validate_search.js 2>&1 | tail -30

